      id: r.int_('id'),
      in_: r.list('in', TradePlayer.fromJson),
      incoming: r.bool_('incoming'),
      money: r.int_('money'),
      out: r.list('out', TradePlayer.fromJson),
      sellOnBp: r.intOrNull('sell_on_bp'),
      status: r.string('status'),
      to: r.object('to', TransferOfferTo.fromJson),
    );
  }

  final int? counterOf;
  final String expiresAt;
  final TransferOfferFrom from;
  final int id;
  final List<TradePlayer> in_;

  /// True when it is mine to answer
  final bool incoming;
  final int money;
  final List<TradePlayer> out;

  /// [X62] The sell-on share promised with it
  final int? sellOnBp;
  final String status;
  final TransferOfferTo to;
}

